<template>
    <div class="account-main-container">
        <div class="account-sidebar">
            <div class="account-sidebar-menu">
                <h2>{{ $t('sidebar.menu') }}</h2>
                <a id="sidebar-links" @click.native="setActive('profile')">{{ $t('sidebar.profile') }}</a>
                <a id="sidebar-links" @click.native="setActive('reports')">{{ $t('sidebar.reports') }}</a>

            </div>
        </div>
        <div class="profile-container">
            <div v-if="activeSection === 'profile'">
                <Profile/>
            </div>

            <div v-else-if="activeSection === 'reports'">
                <ReportsGrid />
            </div>

        </div>
    </div>
</template>

<script>
import Profile from '@/components/Profile.vue';
import ReportsGrid from '@/components/ReportsGrid.vue';
import { useToast } from 'vue-toastification'
import { API_BASE_URL } from '@/config/api';

export default {
    name: 'UserAccount',
    components: {
        Profile,
        ReportsGrid

    },
    data() {
        return {
            user: {
                email: '',
                password: '',
                username: '',
                role: '',
                accountCreatedAt: ''
            },
            error: '',
            url: `${API_BASE_URL}/users`,
            toast: null, // declare a toast variable to be used with toastification library for notifications
            timeout: 2000, 
            activeSection: 'profile', //this controls which section in visible to the user at any time. I set it to the profile page as default


        }
    },
    mounted() {
        this.toast = useToast(); // initiate a toast variable

    },
    methods: {
        setActive(section) {
            try {
                this.activeSection = section
            } catch (error) {
                this.toast && this.toast.error(this.$t('notification.loadingFailed') || 'Loading failed')
            }
        },
        },
    }
</script>